{
  "name": "HP 4395A 网络/频谱/阻抗分析仪",
  "name_en": "HP 4395A Network/Spectrum/Impedance Analyzer",
  "manufacturer": "Hewlett-Packard",
  "description": "HP 4395A 是一款台式射频测试仪器，可进行网络分析、频谱分析以及阻抗测量。它常用于电子与射频实验中测量器件或电路的传输/反射特性、扫频响应、源功率相关响应以及阻抗参数。",
  "description_en": "The HP 4395A is a benchtop RF test instrument for network analysis, spectrum analysis, and impedance measurement. It is commonly used in electronics and RF labs to measure transmission and reflection characteristics, swept-frequency response, source-power-dependent behavior, and impedance-related parameters of devices and circuits.",
  "tag_hints": [
    "network analysis",
    "impedance measurement",
    "spectrum analysis",
    "S-parameter measurement",
    "frequency sweep",
    "RF test instrument"
  ],
  "actions": [
    {
      "action_name": "auto-trace",
      "description": "获取当前扫频曲线数据（x、y）。",
      "description_en": "Get the current trace data (x, y)."
    },
    {
      "action_name": "auto-points",
      "description": "获取或设置扫频点数。",
      "description_en": "Get/set the number of sweep points."
    },
    {
      "action_name": "auto-bandwidth",
      "description": "获取或设置中频带宽（IF Bandwidth）。",
      "description_en": "Get/set the IF bandwidth."
    },
    {
      "action_name": "auto-form",
      "description": "获取或设置显示/测量格式。",
      "description_en": "Get/set the display/measurement format."
    },
    {
      "action_name": "auto-sweepformat",
      "description": "获取或设置扫频格式。",
      "description_en": "Get/set the sweep format."
    },
    {
      "action_name": "auto-paramater",
      "description": "获取或设置测量参数。",
      "description_en": "Get/set the measurement parameter."
    },
    {
      "action_name": "auto-attenuationr",
      "description": "获取或设置 R 端口衰减。",
      "description_en": "Get/set the attenuation of port R."
    },
    {
      "action_name": "auto-attenuationa",
      "description": "获取或设置 A 端口衰减。",
      "description_en": "Get/set the attenuation of port A."
    },
    {
      "action_name": "auto-attenuationb",
      "description": "获取或设置 B 端口衰减。",
      "description_en": "Get/set the attenuation of port B."
    },
    {
      "action_name": "auto-sourcepower",
      "description": "获取或设置源输出功率。",
      "description_en": "Get/set the source output power."
    },
    {
      "action_name": "auto-start",
      "description": "获取或设置起始频率。",
      "description_en": "Get/set the start frequency."
    },
    {
      "action_name": "auto-stop",
      "description": "获取或设置终止频率。",
      "description_en": "Get/set the stop frequency."
    }
  ]
}

